#pragma HLS ARRAY_PARTITION variable=l_seq   complete dim=1
#pragma HLS ARRAY_PARTITION variable=l_table cyclic factor=16 dim=1
#pragma HLS ARRAY_PARTITION variable=l_table cyclic factor=16 dim=2

    const int n = N;

    // =========================================================
